begin;
create extension if not exists pgtap with schema extensions;
select plan(22);
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000601','sheets.designer@example.test'),('00000000-0000-4000-8000-000000000602','sheets.operator@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values
 ('00000000-0000-4000-8000-000000000611','00000000-0000-4000-8000-000000000601','sheets.designer@example.test','Diseño'),
 ('00000000-0000-4000-8000-000000000612','00000000-0000-4000-8000-000000000602','sheets.operator@example.test','Taller');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000000611','designer'),('00000000-0000-4000-8000-000000000612','operator');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000601';
select public.save_customer('00000000-0000-4000-8000-000000000621',null,'{"display_name":"Cliente fichas","notes":"PRIVADO CLIENTE"}');
select lives_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000622','00000000-0000-4000-8000-000000000621',null,null,'PRIVADO NOTA','[{"description":"Trabajo interno A","client_description":"Talonarios comerciales","specifications":"PRIVADO TALLER","quantity":100,"amount":"100","technical_sheet":{"composition":[{"work_type":"Original","copies":"3","paper_color":"Blanco","grammage":"80","perforated":"Sí"}],"number_ranges":[{"from":"000001","to":"000100"}],"observations":"PRIVADO TECNICO"}},{"description":"Trabajo interno B","client_description":"Tarjetas pendientes NO MOSTRAR PDF","quantity":200,"amount":"200"}]')$$,'Crea ficha técnica y descripción comercial');
select is((select client_description from public.order_items where order_id='00000000-0000-4000-8000-000000000622' and position=1),'Talonarios comerciales','Se guarda la descripción para el cliente');
select is((select technical_sheet from public.order_items where order_id='00000000-0000-4000-8000-000000000622' and position=1),'{}'::jsonb,'La nota ya no guarda fichas técnicas por ítem');
select throws_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000623','00000000-0000-4000-8000-000000000621',null,null,'','[{"description":"Inválido","quantity":1,"amount":"100","technical_sheet":{"clave_inventada":"error"}}]')$$,'22023',null,'Valida la estructura técnica también en SQL');
select is((select count(*) from public.orders where id='00000000-0000-4000-8000-000000000623'),0::bigint,'Un detalle inválido revierte toda la nota');
select is(jsonb_array_length(public.customer_completed_summary('00000000-0000-4000-8000-000000000621')->'orders'),0,'El reporte no incluye notas sin trabajos terminados');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000602';
select is(public.production_order('00000000-0000-4000-8000-000000000622')->'technical_sheet','{}'::jsonb,'El taller recibe una ficha común de la nota');
select ok(not((public.production_order('00000000-0000-4000-8000-000000000622')->'items'->0)?'amount'),'La ficha del taller no agrega acceso a precios');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000622',1,'[]')$$,'42501',null,'Operarios no modifican la ficha de Diseño');
select public.complete_production('00000000-0000-4000-8000-000000000622',(public.production_order('00000000-0000-4000-8000-000000000622')->'items'->0->>'id')::uuid,'PRIVADO CIERRE');
select throws_ok($$select public.customer_completed_summary('00000000-0000-4000-8000-000000000621')$$,'42501',null,'El PDF financiero requiere Diseño');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000601';
select is(jsonb_array_length(public.customer_completed_summary('00000000-0000-4000-8000-000000000621')->'orders'->0->'items'),1,'Una nota parcial incluye únicamente su trabajo terminado');
select ok(position('PRIVADO' in public.customer_completed_summary('00000000-0000-4000-8000-000000000621')::text)=0,'El resumen no filtra datos privados del taller o cliente');
select ok(position('NO MOSTRAR PDF' in public.customer_completed_summary('00000000-0000-4000-8000-000000000621')::text)=0,'El texto de trabajos pendientes no llega al PDF');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000000621')->'orders'->0->>'completed_total')::numeric,100::numeric,'El importe terminado se distingue del total de la nota');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000000621')->>'balance')::numeric,300::numeric,'El saldo sigue siendo de la nota completa');
select lives_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000622',1,(select jsonb_agg(jsonb_build_object('id',id,'client_description',client_description,'specifications',specifications,'technical_sheet',technical_sheet||'{"printer_code":"ABC"}'::jsonb)) from public.order_items where order_id='00000000-0000-4000-8000-000000000622'))$$,'Completa la ficha de una nota existente');
select is((select total from public.orders where id='00000000-0000-4000-8000-000000000622'),300::numeric,'Editar la ficha no cambia el importe');
select is((select production_status from public.order_items where order_id='00000000-0000-4000-8000-000000000622' and position=1),'completed','Editar la ficha conserva cierres anteriores');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000622',1,'[]')$$,'40001',null,'Rechaza una versión desactualizada de la ficha');
select public.save_quote('00000000-0000-4000-8000-000000000624',null,'Cliente','','','[{"description":"Trabajo","client_description":"Descripción comercial cotizada","quantity":1,"amount":"50","technical_sheet":{"printing_color":"Negro","number_ranges":[{"from":"0005","to":"0010"}]}}]','00000000-0000-4000-8000-000000000621');
select public.approve_quote('00000000-0000-4000-8000-000000000624',1,'');
select public.create_order_from_quote('00000000-0000-4000-8000-000000000624',2,null,null,null);
select is((select i.technical_sheet from public.order_items i join public.orders o on o.id=i.order_id where o.quote_id='00000000-0000-4000-8000-000000000624'),'{}'::jsonb,'La conversión no vuelve a crear fichas por ítem');
select is((select i.client_description from public.order_items i join public.orders o on o.id=i.order_id where o.quote_id='00000000-0000-4000-8000-000000000624'),'Descripción comercial cotizada','La conversión conserva la descripción para el cliente');
select ok(not has_function_privilege('anon','public.customer_completed_summary(uuid)','EXECUTE'),'El resumen no es público');
reset role;
select * from finish();
rollback;
